// Shared logic for member email (spec docs/member-email-2026-10-17/SPEC.md,
// section 2; migrate_198). Used by `member-email-admin` and
// `member-email-public`. Pure functions and two small fetch helpers; no
// logging here, and nothing in this file ever logs an address or an answer.
//
//   * Tokens: HMAC-SHA256, `base64url(json).base64url(sig)`, signed with
//     `member_email_config.link_secret` (generated by migrate_198). Every
//     token carries a purpose (`p`) and an expiry (`x`, epoch seconds), and
//     a token of one purpose is never accepted for another.
//       admin   { p, e: admin email, x: 12 hours }
//       unsub   { p, u: user id,     x: 5 years }  (List-Unsubscribe link)
//       survey  { p, u: user id, s: survey id, x: 90 days }
//   * Rendering: HTML and plain text from the campaign fields. The body is
//     paragraphs split on blank lines, `**bold**` and `[text](https://...)`;
//     everything else is escaped. Only https links are ever rendered as
//     links; anything else stays visible as plain, escaped text.
//   * Copy lint: the house voice rule (no em dash) plus the field limits.
//   * Surveys: question validation (the shape migrate_198 stores) and answer
//     validation against the questions, the results tally and the CSV.

// ─── Constants ────────────────────────────────────────────────────────

export const SITE_ORIGIN = 'https://volyume.app'
export const FROM_ADDRESS = 'Volyume <news@volyume.app>'
export const WORDMARK_URL = 'https://volyume.app/volyume-wordmark.png'
export const RESEND_EMAILS_URL = 'https://api.resend.com/emails'
export const RESEND_BATCH_URL = 'https://api.resend.com/emails/batch'
export const RESEND_BATCH_MAX = 100

export const ADMIN_SESSION_SECONDS = 12 * 60 * 60
export const UNSUBSCRIBE_TOKEN_SECONDS = 5 * 365 * 24 * 60 * 60
export const SURVEY_TOKEN_SECONDS = 90 * 24 * 60 * 60
export const LOGIN_NONCE_MINUTES = 15
export const MAX_OPEN_LOGINS = 5

export const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
const EM_DASH = '\u2014'
const MAX_TOKEN_LENGTH = 2048

export const FOOTER_TEXT_BEFORE_LINK =
  'You are getting this because you have a Volyume account. You can turn these emails off in the app, in Settings, or '
export const FOOTER_LINK_TEXT = 'unsubscribe here'
export const SURVEY_BUTTON_LABEL = 'Take the short survey'

// ─── CORS and responses ───────────────────────────────────────────────

export function corsHeaders(methods: string): Record<string, string> {
  return {
    'Access-Control-Allow-Origin': SITE_ORIGIN,
    'Access-Control-Allow-Headers': 'content-type',
    'Access-Control-Allow-Methods': methods,
    'Vary': 'Origin',
  }
}

export function jsonResponse(body: unknown, status: number, cors: Record<string, string>): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...cors, 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
  })
}

// ─── base64url ────────────────────────────────────────────────────────

export function base64UrlEncode(bytes: Uint8Array): string {
  let binary = ''
  for (let i = 0; i < bytes.length; i += 1) binary += String.fromCharCode(bytes[i])
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

export function base64UrlDecode(text: string): Uint8Array | null {
  if (!/^[A-Za-z0-9_-]*$/.test(text)) return null
  const padded = text.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((text.length + 3) % 4)
  try {
    const binary = atob(padded)
    const out = new Uint8Array(binary.length)
    for (let i = 0; i < binary.length; i += 1) out[i] = binary.charCodeAt(i)
    return out
  } catch (_) {
    return null
  }
}

// ─── Tokens ───────────────────────────────────────────────────────────

export type TokenPurpose = 'admin' | 'unsub' | 'survey'

export interface TokenPayload {
  p: TokenPurpose
  x: number
  e?: string
  u?: string
  s?: string
}

async function hmacKey(secret: string): Promise<CryptoKey> {
  if (typeof secret !== 'string' || secret.length < 32) throw new Error('link secret missing')
  return await crypto.subtle.importKey(
    'raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign', 'verify'],
  )
}

export async function signToken(payload: TokenPayload, secret: string): Promise<string> {
  const body = base64UrlEncode(new TextEncoder().encode(JSON.stringify(payload)))
  const key = await hmacKey(secret)
  const sig = new Uint8Array(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(body)))
  return `${body}.${base64UrlEncode(sig)}`
}

/**
 * The payload when the token is well formed, correctly signed, of the
 * expected purpose and unexpired; otherwise null. Never throws for a bad
 * token (a missing secret does throw: that is a server fault, not a bad
 * link).
 */
export async function verifyToken(
  token: unknown, secret: string, purpose: TokenPurpose, nowMs: number = Date.now(),
): Promise<TokenPayload | null> {
  if (typeof token !== 'string' || token.length === 0 || token.length > MAX_TOKEN_LENGTH) return null
  const parts = token.split('.')
  if (parts.length !== 2) return null
  const [body, sigText] = parts
  const sig = base64UrlDecode(sigText)
  if (!sig || sig.length !== 32) return null
  const key = await hmacKey(secret)
  // crypto.subtle.verify compares in constant time.
  // `sig` is a fresh Uint8Array (base64UrlDecode), so its buffer is exactly
  // the signature bytes.
  const valid = await crypto.subtle.verify('HMAC', key, sig.buffer as ArrayBuffer, new TextEncoder().encode(body))
  if (!valid) return null
  const raw = base64UrlDecode(body)
  if (!raw) return null
  let payload: unknown
  try { payload = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(raw)) } catch (_) { return null }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return null
  const p = payload as Record<string, unknown>
  if (p.p !== purpose) return null
  if (typeof p.x !== 'number' || !Number.isFinite(p.x) || p.x * 1000 <= nowMs) return null
  if (purpose === 'admin' && (typeof p.e !== 'string' || p.e.length === 0 || p.e.length > 320)) return null
  if (purpose === 'unsub' && (typeof p.u !== 'string' || !UUID_RE.test(p.u))) return null
  if (purpose === 'survey' && (typeof p.u !== 'string' || !UUID_RE.test(p.u)
      || typeof p.s !== 'string' || !UUID_RE.test(p.s))) return null
  return p as unknown as TokenPayload
}

function expiry(nowMs: number, seconds: number): number {
  return Math.floor(nowMs / 1000) + seconds
}

export async function makeAdminSession(email: string, secret: string, nowMs: number = Date.now()) {
  const x = expiry(nowMs, ADMIN_SESSION_SECONDS)
  const session = await signToken({ p: 'admin', e: email, x }, secret)
  return { session, expires_at: new Date(x * 1000).toISOString() }
}

export async function makeUnsubscribeToken(userId: string, secret: string, nowMs: number = Date.now()) {
  return await signToken({ p: 'unsub', u: userId, x: expiry(nowMs, UNSUBSCRIBE_TOKEN_SECONDS) }, secret)
}

export async function makeSurveyToken(userId: string, surveyId: string, secret: string, nowMs: number = Date.now()) {
  return await signToken({ p: 'survey', u: userId, s: surveyId, x: expiry(nowMs, SURVEY_TOKEN_SECONDS) }, secret)
}

export function randomHex(bytes: number): string {
  const b = crypto.getRandomValues(new Uint8Array(bytes))
  return Array.from(b, (v) => v.toString(16).padStart(2, '0')).join('')
}

export async function sha256Hex(text: string): Promise<string> {
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text)))
  return Array.from(digest, (v) => v.toString(16).padStart(2, '0')).join('')
}

// ─── Links ────────────────────────────────────────────────────────────

export function unsubscribePageUrl(token: string): string {
  return `${SITE_ORIGIN}/email/unsubscribe/?t=${encodeURIComponent(token)}`
}

export function oneClickUnsubscribeUrl(supabaseUrl: string, token: string): string {
  return `${supabaseUrl.replace(/\/+$/, '')}/functions/v1/member-email-public?action=unsubscribe&t=${encodeURIComponent(token)}`
}

export function surveyUrl(surveyId: string, token: string | null): string {
  const base = `${SITE_ORIGIN}/survey/?id=${encodeURIComponent(surveyId)}`
  return token ? `${base}&t=${encodeURIComponent(token)}` : base
}

export function adminLoginUrl(nonce: string): string {
  return `${SITE_ORIGIN}/members/?login=${encodeURIComponent(nonce)}`
}

// ─── Escaping and safe links ──────────────────────────────────────────

export function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

/**
 * The normalised URL when `raw` is an absolute https link with a host and no
 * credentials, quotes, spaces or angle brackets; otherwise null. javascript:,
 * data:, http:, protocol-relative and relative links are all refused.
 */
export function safeHttpsUrl(raw: unknown): string | null {
  if (typeof raw !== 'string') return null
  if (raw.length === 0 || raw.length > 2000) return null
  if (!/^https:\/\//i.test(raw)) return null
  if (/[\s"'<>`\\]/.test(raw) || /[\u0000-\u001f\u007f]/.test(raw)) return null
  let url: URL
  try { url = new URL(raw) } catch (_) { return null }
  if (url.protocol !== 'https:' || !url.hostname || url.username || url.password) return null
  return url.href
}

// ─── Body format ──────────────────────────────────────────────────────

type Inline = { kind: 'text'; text: string } | { kind: 'bold'; text: string } | { kind: 'link'; text: string; url: string }

const INLINE_RE = /\*\*([^*\n]{1,500}?)\*\*|\[([^\]\n]{1,200})\]\(([^)\s]{1,2000})\)/g

function parseInline(paragraph: string): Inline[] {
  const out: Inline[] = []
  let last = 0
  for (const m of paragraph.matchAll(INLINE_RE)) {
    const at = m.index ?? 0
    if (at > last) out.push({ kind: 'text', text: paragraph.slice(last, at) })
    if (m[1] !== undefined) {
      out.push({ kind: 'bold', text: m[1] })
    } else {
      const url = safeHttpsUrl(m[3])
      if (url) out.push({ kind: 'link', text: m[2], url })
      else out.push({ kind: 'text', text: m[0] })
    }
    last = at + m[0].length
  }
  if (last < paragraph.length) out.push({ kind: 'text', text: paragraph.slice(last) })
  return out
}

export function splitParagraphs(body: string): string[] {
  return body.replace(/\r\n?/g, '\n').split(/\n[ \t]*\n+/).map((p) => p.trim()).filter((p) => p.length > 0)
}

/** Every `[text](url)` in the body whose url is not a safe https link. */
export function unsafeBodyLinks(body: string): string[] {
  const bad: string[] = []
  for (const m of body.matchAll(INLINE_RE)) {
    if (m[1] === undefined && !safeHttpsUrl(m[3])) bad.push(m[3])
  }
  return bad
}

function inlineHtml(parts: Inline[]): string {
  return parts.map((p) => {
    if (p.kind === 'bold') return `<strong>${escapeHtml(p.text)}</strong>`
    if (p.kind === 'link') {
      return `<a href="${escapeHtml(p.url)}" style="color:#1f5f4a;text-decoration:underline;">${escapeHtml(p.text)}</a>`
    }
    return escapeHtml(p.text).replace(/\n/g, '<br>')
  }).join('')
}

function inlineText(parts: Inline[]): string {
  return parts.map((p) => {
    if (p.kind === 'bold') return p.text
    if (p.kind === 'link') return `${p.text} (${p.url})`
    return p.text
  }).join('')
}

// ─── Rendering ────────────────────────────────────────────────────────

export interface CampaignContent {
  subject: string
  preheader?: string | null
  body: string
  button_label?: string | null
  button_url?: string | null
  survey_id?: string | null
}

export interface RenderLinks {
  unsubscribeUrl: string
  surveyUrl?: string | null
}

function buttonHtml(label: string, url: string): string {
  return `<tr><td style="padding:8px 0 24px 0;"><a href="${escapeHtml(url)}" style="display:inline-block;background:#1f5f4a;color:#ffffff;text-decoration:none;font-weight:600;font-size:16px;line-height:20px;padding:14px 22px;border-radius:10px;">${escapeHtml(label)}</a></td></tr>`
}

export function renderEmail(c: CampaignContent, links: RenderLinks): { subject: string; html: string; text: string } {
  const paragraphs = splitParagraphs(c.body).map(parseInline)
  const buttonUrl = safeHttpsUrl(c.button_url ?? null)
  const buttonLabel = (c.button_label ?? '').trim()
  const survey = c.survey_id && links.surveyUrl ? safeHttpsUrl(links.surveyUrl) : null
  const unsubscribe = safeHttpsUrl(links.unsubscribeUrl)
  if (!unsubscribe) throw new Error('unsubscribe link missing')
  const preheader = (c.preheader ?? '').trim()

  const rows: string[] = []
  rows.push(`<tr><td style="padding:0 0 24px 0;"><img src="${escapeHtml(WORDMARK_URL)}" alt="Volyume" width="140" style="display:block;border:0;height:auto;max-width:140px;"></td></tr>`)
  for (const p of paragraphs) {
    rows.push(`<tr><td style="padding:0 0 16px 0;font-size:16px;line-height:24px;color:#1b1f1d;">${inlineHtml(p)}</td></tr>`)
  }
  if (buttonUrl && buttonLabel) rows.push(buttonHtml(buttonLabel, buttonUrl))
  if (survey) rows.push(buttonHtml(SURVEY_BUTTON_LABEL, survey))
  rows.push(`<tr><td style="padding:24px 0 0 0;border-top:1px solid #e3e6e4;font-size:13px;line-height:20px;color:#5b625e;">${escapeHtml(FOOTER_TEXT_BEFORE_LINK)}<a href="${escapeHtml(unsubscribe)}" style="color:#5b625e;text-decoration:underline;">${escapeHtml(FOOTER_LINK_TEXT)}</a>.</td></tr>`)

  const html = [
    '<!doctype html>',
    '<html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">',
    `<title>${escapeHtml(c.subject)}</title></head>`,
    '<body style="margin:0;padding:0;background:#f4f5f4;">',
    preheader
      ? `<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;">${escapeHtml(preheader)}</div>`
      : '',
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f4;"><tr><td align="center" style="padding:24px 16px;">',
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:14px;"><tr><td style="padding:28px 24px;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,Helvetica,Arial,sans-serif;">',
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0">',
    rows.join(''),
    '</table></td></tr></table></td></tr></table></body></html>',
  ].join('')

  const textParts: string[] = paragraphs.map(inlineText)
  if (buttonUrl && buttonLabel) textParts.push(`${buttonLabel}: ${buttonUrl}`)
  if (survey) textParts.push(`${SURVEY_BUTTON_LABEL}: ${survey}`)
  textParts.push(`${FOOTER_TEXT_BEFORE_LINK}${FOOTER_LINK_TEXT}: ${unsubscribe}`)
  return { subject: c.subject, html, text: textParts.join('\n\n') }
}

// ─── Copy lint ────────────────────────────────────────────────────────

export interface LintProblem {
  field: string
  code: string
  message: string
}

const LIMITS: Record<string, number> = { subject: 150, preheader: 200, body: 20000, button_label: 40 }

/** Every reason this campaign may not be sent. Empty means it may. */
export function lintCampaign(c: Partial<CampaignContent>): LintProblem[] {
  const problems: LintProblem[] = []
  const subject = typeof c.subject === 'string' ? c.subject : ''
  const body = typeof c.body === 'string' ? c.body : ''
  if (subject.trim().length === 0) problems.push({ field: 'subject', code: 'required', message: 'The subject is empty.' })
  if (body.trim().length === 0) problems.push({ field: 'body', code: 'required', message: 'The message is empty.' })
  for (const field of ['subject', 'preheader', 'body', 'button_label'] as const) {
    const value = c[field]
    if (value == null) continue
    if (typeof value !== 'string') {
      problems.push({ field, code: 'bad_type', message: `The ${field.replace('_', ' ')} must be text.` })
      continue
    }
    if (value.length > LIMITS[field]) {
      problems.push({ field, code: 'too_long', message: `The ${field.replace('_', ' ')} is longer than ${LIMITS[field]} characters.` })
    }
    if (value.includes(EM_DASH)) {
      problems.push({ field, code: 'em_dash', message: `The ${field.replace('_', ' ')} has an em dash. Use a full stop, comma or colon.` })
    }
    if (field !== 'body' && /[\r\n]/.test(value)) {
      problems.push({ field, code: 'line_break', message: `The ${field.replace('_', ' ')} must be on one line.` })
    }
  }
  if (body && unsafeBodyLinks(body).length > 0) {
    problems.push({ field: 'body', code: 'link_not_https', message: 'Every link in the message must start with https://.' })
  }
  const label = typeof c.button_label === 'string' ? c.button_label.trim() : ''
  const url = c.button_url
  if (url != null && url !== '' && !safeHttpsUrl(url)) {
    problems.push({ field: 'button_url', code: 'link_not_https', message: 'The button link must start with https://.' })
  }
  if ((label !== '') !== (url != null && url !== '')) {
    problems.push({ field: 'button_label', code: 'button_incomplete', message: 'A button needs both a label and a link.' })
  }
  return problems
}

// ─── Surveys ──────────────────────────────────────────────────────────

export type QuestionType = 'single' | 'multi' | 'text'

export interface SurveyQuestion {
  id: string
  type: QuestionType
  prompt: string
  options?: string[]
  required: boolean
}

export type Validated<T> = { ok: true; value: T } | { ok: false; error: string; question?: string }

const QUESTION_ID_RE = /^q[1-9][0-9]?$/
export const MAX_QUESTIONS = 20
export const MAX_OPTIONS = 10
export const MAX_TEXT_ANSWER = 2000

export function validateSurveyMeta(title: unknown, intro: unknown): Validated<{ title: string; intro: string | null }> {
  if (typeof title !== 'string' || title.trim().length < 1 || title.trim().length > 120) return { ok: false, error: 'bad_title' }
  if (intro != null && typeof intro !== 'string') return { ok: false, error: 'bad_intro' }
  const introText = typeof intro === 'string' ? intro.trim() : ''
  if (introText.length > 1000) return { ok: false, error: 'bad_intro' }
  if (title.includes(EM_DASH) || introText.includes(EM_DASH)) return { ok: false, error: 'em_dash' }
  return { ok: true, value: { title: title.trim(), intro: introText || null } }
}

export function validateQuestions(raw: unknown): Validated<SurveyQuestion[]> {
  if (!Array.isArray(raw) || raw.length < 1 || raw.length > MAX_QUESTIONS) return { ok: false, error: 'bad_question_count' }
  const seen = new Set<string>()
  const out: SurveyQuestion[] = []
  for (const item of raw) {
    if (!item || typeof item !== 'object' || Array.isArray(item)) return { ok: false, error: 'bad_question' }
    const q = item as Record<string, unknown>
    const id = q.id
    if (typeof id !== 'string' || !QUESTION_ID_RE.test(id)) return { ok: false, error: 'bad_question_id' }
    if (seen.has(id)) return { ok: false, error: 'duplicate_question_id', question: id }
    seen.add(id)
    if (q.type !== 'single' && q.type !== 'multi' && q.type !== 'text') return { ok: false, error: 'bad_question_type', question: id }
    if (typeof q.prompt !== 'string' || q.prompt.trim().length < 1 || q.prompt.trim().length > 300) {
      return { ok: false, error: 'bad_prompt', question: id }
    }
    if (q.prompt.includes(EM_DASH)) return { ok: false, error: 'em_dash', question: id }
    if (typeof q.required !== 'boolean') return { ok: false, error: 'bad_required', question: id }
    const question: SurveyQuestion = { id, type: q.type, prompt: q.prompt.trim(), required: q.required }
    if (q.type === 'text') {
      if (q.options != null && !(Array.isArray(q.options) && q.options.length === 0)) {
        return { ok: false, error: 'text_question_has_options', question: id }
      }
    } else {
      if (!Array.isArray(q.options) || q.options.length < 1 || q.options.length > MAX_OPTIONS) {
        return { ok: false, error: 'bad_option_count', question: id }
      }
      const options: string[] = []
      for (const o of q.options) {
        if (typeof o !== 'string' || o.trim().length < 1 || o.trim().length > 120) return { ok: false, error: 'bad_option', question: id }
        if (o.includes(EM_DASH)) return { ok: false, error: 'em_dash', question: id }
        if (options.includes(o.trim())) return { ok: false, error: 'duplicate_option', question: id }
        options.push(o.trim())
      }
      question.options = options
    }
    out.push(question)
  }
  return { ok: true, value: out }
}

export type SurveyAnswers = Record<string, string | string[]>

/**
 * The answers, normalised (trimmed text, unanswered questions left out),
 * when every key names a question, every value fits its question's type and
 * options, no text is longer than 2,000 characters and every required
 * question is answered; otherwise the first problem.
 */
export function validateAnswers(questions: SurveyQuestion[], raw: unknown): Validated<SurveyAnswers> {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return { ok: false, error: 'bad_answers' }
  const input = raw as Record<string, unknown>
  const byId = new Map(questions.map((q) => [q.id, q]))
  for (const key of Object.keys(input)) {
    if (!byId.has(key)) return { ok: false, error: 'unknown_question', question: key.slice(0, 20) }
  }
  const out: SurveyAnswers = {}
  for (const q of questions) {
    const value = input[q.id]
    let answered = false
    if (value === undefined || value === null) {
      answered = false
    } else if (q.type === 'single') {
      if (typeof value !== 'string') return { ok: false, error: 'bad_type', question: q.id }
      if (value !== '') {
        if (!(q.options ?? []).includes(value)) return { ok: false, error: 'bad_option', question: q.id }
        out[q.id] = value
        answered = true
      }
    } else if (q.type === 'multi') {
      if (!Array.isArray(value)) return { ok: false, error: 'bad_type', question: q.id }
      const picked: string[] = []
      for (const v of value) {
        if (typeof v !== 'string' || !(q.options ?? []).includes(v)) return { ok: false, error: 'bad_option', question: q.id }
        if (picked.includes(v)) return { ok: false, error: 'duplicate_option', question: q.id }
        picked.push(v)
      }
      if (picked.length > 0) {
        out[q.id] = picked
        answered = true
      }
    } else {
      if (typeof value !== 'string') return { ok: false, error: 'bad_type', question: q.id }
      const text = value.trim()
      if (text.length > MAX_TEXT_ANSWER) return { ok: false, error: 'text_too_long', question: q.id }
      if (text.length > 0) {
        out[q.id] = text
        answered = true
      }
    }
    if (q.required && !answered) return { ok: false, error: 'required_missing', question: q.id }
  }
  return { ok: true, value: out }
}

export interface AnswerRow {
  created_at: string
  user_id: string | null
  answers: SurveyAnswers
}

export function surveyResults(questions: SurveyQuestion[], rows: AnswerRow[]) {
  const newestFirst = [...rows].sort((a, b) => (a.created_at < b.created_at ? 1 : a.created_at > b.created_at ? -1 : 0))
  return {
    total: rows.length,
    questions: questions.map((q) => {
      if (q.type === 'text') {
        const answers: { text: string; created_at: string }[] = []
        for (const r of newestFirst) {
          const v = r.answers?.[q.id]
          if (typeof v === 'string' && v.length > 0) answers.push({ text: v, created_at: r.created_at })
        }
        return { id: q.id, type: q.type, prompt: q.prompt, answered: answers.length, answers }
      }
      const counts: Record<string, number> = {}
      for (const o of q.options ?? []) counts[o] = 0
      let answered = 0
      for (const r of rows) {
        const v = r.answers?.[q.id]
        const picked = Array.isArray(v) ? v : typeof v === 'string' ? [v] : []
        if (picked.length > 0) answered += 1
        for (const p of picked) if (p in counts) counts[p] += 1
      }
      return { id: q.id, type: q.type, prompt: q.prompt, options: q.options ?? [], answered, counts }
    }),
  }
}

/** One CSV cell: quoted, quotes doubled, and a leading formula character neutralised. */
export function csvCell(value: string): string {
  const safe = /^[=+\-@\t\r]/.test(value) ? `'${value}` : value
  return `"${safe.replace(/"/g, '""')}"`
}

export function surveyCsv(questions: SurveyQuestion[], rows: AnswerRow[]): string {
  const header = ['Submitted at', 'From an email link', ...questions.map((q) => q.prompt)]
  const lines = [header.map(csvCell).join(',')]
  const newestFirst = [...rows].sort((a, b) => (a.created_at < b.created_at ? 1 : a.created_at > b.created_at ? -1 : 0))
  for (const r of newestFirst) {
    const cells = [r.created_at, r.user_id ? 'Yes' : 'No']
    for (const q of questions) {
      const v = r.answers?.[q.id]
      cells.push(Array.isArray(v) ? v.join('; ') : typeof v === 'string' ? v : '')
    }
    lines.push(cells.map(csvCell).join(','))
  }
  return lines.join('\r\n') + '\r\n'
}

// ─── Request bodies ───────────────────────────────────────────────────

/** Read a small text body with a hard byte cap (the one-click form post). */
export async function readBoundedText(req: Request, maxBytes: number): Promise<string | null> {
  const declaredRaw = req.headers.get('content-length')
  if (declaredRaw != null) {
    const declared = Number(declaredRaw)
    if (!Number.isSafeInteger(declared) || declared < 0 || declared > maxBytes) return null
  }
  if (!req.body) return ''
  const reader = req.body.getReader()
  const chunks: Uint8Array[] = []
  let total = 0
  try {
    while (true) {
      // eslint-disable-next-line no-await-in-loop
      const { done, value } = await reader.read()
      if (done) break
      if (!value) continue
      total += value.byteLength
      if (total > maxBytes) {
        await reader.cancel('payload too large').catch(() => {})
        return null
      }
      chunks.push(value)
    }
  } finally {
    reader.releaseLock()
  }
  const bytes = new Uint8Array(total)
  let offset = 0
  for (const chunk of chunks) {
    bytes.set(chunk, offset)
    offset += chunk.byteLength
  }
  try { return new TextDecoder('utf-8', { fatal: true }).decode(bytes) } catch (_) { return null }
}

// ─── Resend ───────────────────────────────────────────────────────────

export interface OutgoingEmail {
  from: string
  to: string[]
  subject: string
  html: string
  text: string
  reply_to?: string
  headers?: Record<string, string>
}

export function unsubscribeHeaders(oneClickUrl: string): Record<string, string> {
  return {
    'List-Unsubscribe': `<${oneClickUrl}>`,
    'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click',
  }
}

/**
 * A short, address-free error code from a provider response. Resend's
 * `message` can quote an address, so only its `name` is ever kept.
 */
function providerErrorCode(status: number, body: unknown): string {
  const name = body && typeof body === 'object' ? (body as Record<string, unknown>).name : null
  const safeName = typeof name === 'string' ? name.toLowerCase().replace(/[^a-z_]/g, '').slice(0, 60) : ''
  return safeName ? `http_${status}_${safeName}` : `http_${status}`
}

export type SendResult = { ok: true; ids: string[] } | { ok: false; status: number; code: string }

async function postResend(apiKey: string, url: string, payload: unknown): Promise<{ status: number; body: unknown }> {
  const res = await fetch(url, {
    method: 'POST',
    headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  })
  let body: unknown = null
  try { body = await res.json() } catch (_) { body = null }
  return { status: res.status, body }
}

export async function sendOne(apiKey: string, email: OutgoingEmail): Promise<SendResult> {
  try {
    const { status, body } = await postResend(apiKey, RESEND_EMAILS_URL, email)
    if (status >= 200 && status < 300) {
      const id = body && typeof body === 'object' ? (body as Record<string, unknown>).id : null
      return { ok: true, ids: [typeof id === 'string' ? id : ''] }
    }
    return { ok: false, status, code: providerErrorCode(status, body) }
  } catch (_) {
    return { ok: false, status: 0, code: 'network_error' }
  }
}

/** At most RESEND_BATCH_MAX emails; ids come back in the order sent. */
export async function sendBatch(apiKey: string, emails: OutgoingEmail[]): Promise<SendResult> {
  if (emails.length === 0) return { ok: true, ids: [] }
  if (emails.length > RESEND_BATCH_MAX) return { ok: false, status: 0, code: 'batch_too_large' }
  try {
    const { status, body } = await postResend(apiKey, RESEND_BATCH_URL, emails)
    if (status >= 200 && status < 300) {
      const data = body && typeof body === 'object' ? (body as Record<string, unknown>).data : null
      const ids = Array.isArray(data)
        ? data.map((d) => (d && typeof d === 'object' && typeof (d as Record<string, unknown>).id === 'string'
          ? (d as Record<string, unknown>).id as string : ''))
        : []
      return { ok: true, ids }
    }
    return { ok: false, status, code: providerErrorCode(status, body) }
  } catch (_) {
    return { ok: false, status: 0, code: 'network_error' }
  }
}
